$r=New-Object System.IO.StreamReader(New-Object System.IO.Compression.GZipStream([System.IO.File]::OpenRead("logs/latest.log"),[System.IO.Compression.CompressionMode]::Decompress)); $sb=New-Object System.Text.StringBuilder(); $buf=New-Object char[8192]; while(($n=$r.Read($buf,0,$buf.Length))-gt 0){$sb.Append($buf,0,$n)|Out-Null}; $t=$sb.ToString(); $i=$t.LastIndexOf("unavailable"); if($i -ge 0){Write-Host "IDX $i"; Write-Host $t.Substring([Math]::Max(0,$i-1000),[Math]::Min(2000,$t.Length-$i))} else { Write-Host "NOT FOUND"; Write-Host $t.Substring([Math]::Max(0,$t.Length-1500)) }
